using System.Collections.Generic;
using UnityEngine;
using NursingQuiz.Core;

namespace NursingQuiz.Data
{
    /// <summary>
    /// A collection of questions for one category + theme + tier combination.
    /// Generated by QuestionBankImporter -- one asset per source CSV file.
    /// </summary>
    public class QuestionBank : ScriptableObject
    {
        public string category;
        public string theme;
        public DifficultyTier tier;
        public string sourceFileName;

        public List<QuestionData> questions = new List<QuestionData>();
    }
}
